def flatten_dict(d):
    out = {}
    def walk(cur, prefix):
        for k, v in cur.items():
            key = prefix + '.' + k if prefix else k
            if isinstance(v, dict):
                walk(v, key)
            else:
                out[key] = v
    walk(d, '')
    return out
